 /** Message keys per language, for checks. */
 export const messageKeys = (lang) => Object.keys(MESSAGES[lang] ?? {});
+
+/** The best supported language for an Accept-Language header, else `fallback`. */
+export function pickLanguage(header, fallback = LANGUAGES[0]) {
+  if (typeof header !== "string") return fallback;
+  const ranked = header
+    .split(",")
+    .map((part, i) => {
+      const [tag, ...attrs] = part.trim().split(";");
+      let q = 1;
+      for (const a of attrs) {
+        const m = /^\s*q\s*=\s*(\S*)\s*$/i.exec(a);
+        if (m) q = /^(0(\.\d{0,3})?|1(\.0{0,3})?)$/.test(m[1]) ? Number(m[1]) : 0;
+      }
+      return { lang: tag.trim().toLowerCase().split("-")[0], q, i };
+    })
+    .filter((r) => r.q > 0 && LANGUAGES.includes(r.lang))
+    .sort((a, b) => b.q - a.q || a.i - b.i);
+  return ranked.length ? ranked[0].lang : fallback;
+}
